// Pure-virtual interface to be implemented by a server.
// This interface uses typed channels (i.e. |::fidl::ClientEnd<::fuchsia_hardware_network::Session>|
// and |::fidl::ServerEnd<::fuchsia_hardware_network::Session>|).
template<>
class ::fidl::WireServer<::fuchsia_hardware_network::Session> : public ::fidl::internal::IncomingMessageDispatcher {
  public:
  WireServer() = default;
  virtual ~WireServer() = default;

  // The FIDL protocol type that is implemented by this server.
  using _EnclosingProtocol = ::fuchsia_hardware_network::Session;

  using Handler = fidl::ProtocolHandler<::fuchsia_hardware_network::Session>;

    using AttachCompleter = ::fidl::internal::WireCompleter<::fuchsia_hardware_network::Session::Attach>;
      using AttachRequestView = ::fuchsia_hardware_network::wire::SessionAttachRequest*;

/// Attaches the session to `port`.
///
/// Once attached, the session starts to receive the subscribed frames over
/// the data FIFOs and it may send frames destined to the specified `port`.
///
/// + request `port` port to subscribe to.
/// + request `rx_frames` Frame types of interest on the port.
/// * error `ZX_ERR_NOT_FOUND` if `port` is not valid.
/// * error `ZX_ERR_INVALID_ARGS` if `rx_frames` is not a subset of the
/// port's supported frames.
/// * error `ZX_ERR_ALREADY_BOUND` if `port` is already attached.
  virtual void Attach(
      ::fuchsia_hardware_network::wire::SessionAttachRequest* request,
    AttachCompleter::Sync& completer) = 0;

    using DetachCompleter = ::fidl::internal::WireCompleter<::fuchsia_hardware_network::Session::Detach>;
      using DetachRequestView = ::fuchsia_hardware_network::wire::SessionDetachRequest*;

/// Detaches the session from `port`.
///
/// Once detached, the session stops receiving frames from `port`. Frames
/// sent to a detached port may be returned with an error. It is not
/// necessary to call `Detach` on ports that are removed from the device,
/// doing so causes `ZX_ERR_NOT_FOUND` to be returned.
///
/// + request `port` port to subscribe to.
/// * error `ZX_ERR_NOT_FOUND` if the session is not currently attached to
/// the port.
  virtual void Detach(
      ::fuchsia_hardware_network::wire::SessionDetachRequest* request,
    DetachCompleter::Sync& completer) = 0;

    using CloseCompleter = ::fidl::internal::WireCompleter<::fuchsia_hardware_network::Session::Close>;

/// Cleanly closes a session.
///
/// This will cause the session to send a `ZX_ERR_CANCELLED` epitaph and
/// proceed to close the Session channel. Clients may only assume that they
/// own all the buffers that are currently owned by the session (sent over
/// either the rx or tx FIFOs) once the epitaph is received. Closing the rx
/// or tx FIFO is equivalent to calling `Close`.
  virtual void Close(
    CloseCompleter::Sync& completer) = 0;

    using WatchDelegatedRxLeaseCompleter = ::fidl::internal::WireCompleter<::fuchsia_hardware_network::Session::WatchDelegatedRxLease>;

/// Watchers for delegated receive wakeup leases.
///
/// Calls block until a lease is delegated by the device. If a call to
/// `WatchDelegatedRxLease` is made while a previous call is blocking, the
/// session is closed with `ZX_ERR_BAD_STATE`. Will never yield any values
/// for sessions created without [`SessionFlags.RECEIVE_RX_POWER_LEASES`].
///
/// Given a single lease is assumed sufficient to keep the system awake, the
/// server only keeps a single lease in its buffer. If a new delegated lease
/// becomes available and the client hasn't popped the previous one with a
/// call to `WatchDelegatedRxLease`, the server drops the previously pending
/// lease.
///
/// See [`DelegatedRxLease`] for how to handle delegated leases.
  virtual void WatchDelegatedRxLease(
    WatchDelegatedRxLeaseCompleter::Sync& completer) = 0;

    using RegisterForTxCompleter = ::fidl::internal::WireCompleter<::fuchsia_hardware_network::Session::RegisterForTx>;
      using RegisterForTxRequestView = ::fuchsia_hardware_network::wire::SessionRegisterForTxRequest*;

/// Asks the network device to register the VMO for Tx.
///
/// The network device prepares the VMOs in order and stops at the first
/// error if any. It returns how many VMOs have been prepared alongside with
/// the first error encountered. Note that network-device itself does not
/// try to release earlier VMOs for a later error. It is up to the client
/// how to recover from an error.
///
/// * error `ZX_ERR_NOT_FOUND` if any of the VmoId is unknown.
/// * error other zx status that can be reported by the driver.
  virtual void RegisterForTx(
      ::fuchsia_hardware_network::wire::SessionRegisterForTxRequest* request,
    RegisterForTxCompleter::Sync& completer) = 0;

    using UnregisterForTxCompleter = ::fidl::internal::WireCompleter<::fuchsia_hardware_network::Session::UnregisterForTx>;
      using UnregisterForTxRequestView = ::fuchsia_hardware_network::wire::SessionUnregisterForTxRequest*;

/// Tells the device that the client will no longer use the VMO for Tx,
/// if the VMO is also unused for Rx, the device is free to release it
/// at the implementation driver.
///
/// The network device processes the VMOs in order and stops at the first
/// error if any. It returns how many VMOs have been marked as unused for Tx
/// alongside with the first error encountered. Note that network-device
/// itself does not try to re-register earlier VMOs for a later error. It is
/// up to the client how to recover from an error.
///
/// * error `ZX_ERR_NOT_FOUND` if any of the VmoId is unknown.
/// * error other zx status that can be reported by the driver.
  virtual void UnregisterForTx(
      ::fuchsia_hardware_network::wire::SessionUnregisterForTxRequest* request,
    UnregisterForTxCompleter::Sync& completer) = 0;

  // |bind_handler| returns a handler that binds incoming connections to this
  // server implementation.
  //
  // The returned handler borrows the server instance.
  // The server must outlive the provided |dispatcher|. Only after
  // the dispatcher is shutdown will it be safe to destroy the servers.
  // The server should not be moved.
  Handler bind_handler(async_dispatcher_t* dispatcher);

  private:
  void dispatch_message(
    ::fidl::IncomingHeaderAndMessage&& msg, ::fidl::Transaction* txn,
    ::fidl::internal::MessageStorageViewBase* storage_view) final;
};

namespace fuchsia_hardware_network {

class Service final {
  Service() = default;
 public:
  static constexpr bool kIsService = true;
  static constexpr char Name[] = "fuchsia.hardware.network.Service";
  using Transport = ::fidl::internal::ChannelTransport;

  using ServiceInstanceHandler = fidl::ServiceInstanceHandler<::fidl::internal::ChannelTransport>;

  class Device final {
   public:
    static constexpr bool kIsServiceMember = true;
    static constexpr char Name[] = "device";
    static constexpr char ServiceName[] = "fuchsia.hardware.network.Service";
    using ProtocolType = ::fuchsia_hardware_network::Device;
    using ServiceType = Service;
  };

  class DeviceTopology final {
   public:
    static constexpr bool kIsServiceMember = true;
    static constexpr char Name[] = "device_topology";
    static constexpr char ServiceName[] = "fuchsia.hardware.network.Service";
    using ProtocolType = ::fuchsia_device_fs::TopologicalPath;
    using ServiceType = Service;
  };

  // Client protocol for connecting to member protocols of a service instance.
  class ServiceClient final {
    ServiceClient() = delete;
   public:
    ServiceClient(::zx::channel dir, ::fidl::internal::ConnectMemberFunc connect_func)
        : dir_(std::move(dir)), connect_func_(connect_func) {}

    // Connects |server_end| to the member protocol "device".
    //
    // # Errors
    //
    // On failure, returns a |zx::error| with status != ZX_OK.
    // Failures can occur if there was an issue making a |fuchsia.io.Directory/Open| call.
    //
    // Since the call to |Open| is asynchronous, an error sent by the remote end will not
    // result in a failure of this method. Any errors sent by the remote will appear on
    // the reciprocal |ClientEnd| for the |ServerEnd| passed into this method.
    ::zx::result<> connect_device(::fidl::ServerEnd<::fuchsia_hardware_network::Device> server_end) {
      return connect_func_(
          ::zx::unowned_channel(dir_),
          ::fidl::StringView("device"),
          ::fidl::internal::MakeAnyTransport(server_end.TakeChannel()));
    }

    // Connects to the member protocol "device".
    //
    // # Errors
    //
    // On failure, returns a |zx::error| with status != ZX_OK.
    // Failures can occur if channel creation failed, or if there was an issue making
    // a |fuchsia.io.Directory/Open| call.
    //
    // Since the call to |Open| is asynchronous, an error sent by the remote end will not
    // result in a failure of this method. Any errors sent by the remote will appear on
    // the |ClientEnd| returned from this method.
    ::zx::result<::fidl::ClientEnd<::fuchsia_hardware_network::Device>> connect_device() {
      ::zx::result endpoints = ::fidl::CreateEndpoints<::fuchsia_hardware_network::Device>();
      if (endpoints.is_error()) {
        return endpoints.take_error();
      }
      ::zx::result connection = connect_device(std::move(endpoints->server));
      if (connection.is_error()) {
        return connection.take_error();
      }
      return ::zx::ok(std::move(endpoints->client));
    }

    // Connects |server_end| to the member protocol "device_topology".
    //
    // # Errors
    //
    // On failure, returns a |zx::error| with status != ZX_OK.
    // Failures can occur if there was an issue making a |fuchsia.io.Directory/Open| call.
    //
    // Since the call to |Open| is asynchronous, an error sent by the remote end will not
    // result in a failure of this method. Any errors sent by the remote will appear on
    // the reciprocal |ClientEnd| for the |ServerEnd| passed into this method.
    ::zx::result<> connect_device_topology(::fidl::ServerEnd<::fuchsia_device_fs::TopologicalPath> server_end) {
      return connect_func_(
          ::zx::unowned_channel(dir_),
          ::fidl::StringView("device_topology"),
          ::fidl::internal::MakeAnyTransport(server_end.TakeChannel()));
    }

    // Connects to the member protocol "device_topology".
    //
    // # Errors
    //
    // On failure, returns a |zx::error| with status != ZX_OK.
    // Failures can occur if channel creation failed, or if there was an issue making
    // a |fuchsia.io.Directory/Open| call.
    //
    // Since the call to |Open| is asynchronous, an error sent by the remote end will not
    // result in a failure of this method. Any errors sent by the remote will appear on
    // the |ClientEnd| returned from this method.
    ::zx::result<::fidl::ClientEnd<::fuchsia_device_fs::TopologicalPath>> connect_device_topology() {
      ::zx::result endpoints = ::fidl::CreateEndpoints<::fuchsia_device_fs::TopologicalPath>();
      if (endpoints.is_error()) {
        return endpoints.take_error();
      }
      ::zx::result connection = connect_device_topology(std::move(endpoints->server));
      if (connection.is_error()) {
        return connection.take_error();
      }
      return ::zx::ok(std::move(endpoints->client));
    }

   private:
    ::zx::channel dir_;
    ::fidl::internal::ConnectMemberFunc connect_func_;
  };

  // Facilitates member protocol registration for servers.
  class InstanceHandler final : public fidl::ServiceInstanceHandler<::fidl::internal::ChannelTransport> {
   public:
    struct Members {
        MemberHandler<::fuchsia_hardware_network::Device> device;
        MemberHandler<::fuchsia_device_fs::TopologicalPath> device_topology;
    };

    InstanceHandler() = default;

    // Construct an instance handler for a FIDL service. Protocol handlers not present in |members|
    // will not be registered.
    InstanceHandler(Members members) {
      // This should always be ZX_OK. That's because the only possible
      // error is ZX_ERR_ALREADY_EXISTS which is impossible to occur as fidlc
      // won't allow service declarations with duplicated names.
        if (members.device) {
          ZX_ASSERT(add_device(std::move(members.device)).status_value() == ZX_OK);
        }
        if (members.device_topology) {
          ZX_ASSERT(add_device_topology(std::move(members.device_topology)).status_value() == ZX_OK);
        }
    }

    // Adds member "device" to the service instance. |handler| will be
    // invoked on connection attempts.
    //
    // # Errors
    //
    // Returns ZX_ERR_ALREADY_EXISTS if the member was already added.
    // Returns ZX_ERR_INVALID_ARGS if |handler| is not initialized.
    ::zx::result<> add_device(
        MemberHandler<::fuchsia_hardware_network::Device> handler) {
      return this->AddMember<::fuchsia_hardware_network::Device>(std::move(handler), "device");
    }

    // Adds member "device_topology" to the service instance. |handler| will be
    // invoked on connection attempts.
    //
    // # Errors
    //
    // Returns ZX_ERR_ALREADY_EXISTS if the member was already added.
    // Returns ZX_ERR_INVALID_ARGS if |handler| is not initialized.
    ::zx::result<> add_device_topology(
        MemberHandler<::fuchsia_device_fs::TopologicalPath> handler) {
      return this->AddMember<::fuchsia_device_fs::TopologicalPath>(std::move(handler), "device_topology");
    }

  };
};

  }  // namespace fuchsia_hardware_network

